#!/usr/bin/env python3
"""Run C1 Unit10 cumulative recalibration with an additional cross-domain review layer."""
from pathlib import Path
SOURCE=Path(__file__).with_name('recalibrate_final_arabic_c1_unit10.py')
text=SOURCE.read_text(encoding='utf-8')
patches={
"قالت الباحثة إن التقرير المتقدم لا يطيل النص لمجرد إظهار التعقيد، بل يكشف نقاط الانتقال التي يغير عندها نوع السؤال: من القياس إلى التفسير، ومن التفسير إلى الأولوية، ومن الأولوية إلى التزام يمكن مراجعته.''',":"قالت الباحثة إن التقرير المتقدم لا يطيل النص لمجرد إظهار التعقيد، بل يكشف نقاط الانتقال التي يغير عندها نوع السؤال: من القياس إلى التفسير، ومن التفسير إلى الأولوية، ومن الأولوية إلى التزام يمكن مراجعته. ثم أخفت اللجنة توصيتها النهائية وأعطت مراجعًا جديدًا الأدلة والأوزان وخطة الاختبار فقط. استطاع الوصول إلى قرار قريب لكنه اختلف في مقدار ما يمنحه للاستقرار. لم تعد النتيجة غامضة؛ صار الاختلاف نفسه قابلًا للتحديد بوصفه وزنًا مهنيًا لا خلافًا على البيانات. أضافت اللجنة هذا المثال إلى الدليل التدريبي حتى يعرف القارئ أن الشفافية لا تعني أن كل شخص سيختار الشيء نفسه، بل أن موضع التباين يصبح ظاهرًا ويمكن مناقشته أو تغييره إذا تغيرت أهداف المؤسسة.''',",
"قالت هالة إن القياس المؤسسي واللغة يتفاعلان: عندما نضع تعريفًا للوضوح، يغير الناس كتابتهم وفقه، ولذلك يجب أن يقيس النظام الغاية ويعيد فحص تمثيله لها بدل أن يصبح الشكل الذي يسهل عده هو الغاية نفسها.''',":"قالت هالة إن القياس المؤسسي واللغة يتفاعلان: عندما نضع تعريفًا للوضوح، يغير الناس كتابتهم وفقه، ولذلك يجب أن يقيس النظام الغاية ويعيد فحص تمثيله لها بدل أن يصبح الشكل الذي يسهل عده هو الغاية نفسها. وفي اختبار لاحق غيرت المؤسسة ترتيب الأمثلة والتعليمات من دون تغيير المهمة الأساسية. إذا انهارت النتيجة بسبب هذا التغيير الصغير، فهذا يعني أن الموظفين تعلموا الاختبار أكثر مما تعلموا التواصل بوضوح. بقي الأداء مستقرًا نسبيًا في بعض المراكز وتراجع في أخرى، فاستعمل الفريق الفرق لتحديد أين يحتاج التدريب إلى فهم أعمق للغرض لا حفظ نموذج. كما أبقوا قناة مفتوحة لتعليقات المستخدمين التي لا تدخل مباشرة في الدرجة، حتى لا يغلق النظام نفسه على ما يستطيع قياسه فقط.''',",
"قالت اللجنة إن هذا ليس ترددًا؛ القرار الجيد تحت عدم اليقين يحدد مسبقًا كيف ستغيره المعرفة الجديدة. ما يجب تجنبه هو أن يصبح الإجراء مؤقتًا في الاسم فقط ثم يستمر لأن أحدًا لم يحدد شرطًا للعودة.''',":"قالت اللجنة إن هذا ليس ترددًا؛ القرار الجيد تحت عدم اليقين يحدد مسبقًا كيف ستغيره المعرفة الجديدة. ما يجب تجنبه هو أن يصبح الإجراء مؤقتًا في الاسم فقط ثم يستمر لأن أحدًا لم يحدد شرطًا للعودة. ولهذا سجلت الجهة أيضًا صاحب القرار المسؤول عن كل مراجعة والموعد الذي يجب أن تقع فيه. إذا لم تظهر معلومات جديدة، لا يعني ذلك تلقائيًا أن القيد يستمر؛ يعود القرار إلى الدليل المتاح ويحتاج إلى تبرير جديد. كما اختبرت اللجنة أثر التأخير الإداري نفسه، لأن إجراءً محدودًا قد يصبح واسع الأثر إذا طال انتظار المراجعة. أدخلت مدة التنفيذ ضمن العبء، فصار الزمن جزءًا من التناسب لا مجرد تفصيل تنظيمي.''',",
"أفضل درس ليس «خاطر تربح»، بل «اعرف ما الذي كان معلومًا، وما البدائل، وما قدرة القرار على تحمل الخطأ، ثم لا تسمح للنهاية أن تعيد كتابة جودة البداية».''',":"أفضل درس ليس «خاطر تربح»، بل «اعرف ما الذي كان معلومًا، وما البدائل، وما قدرة القرار على تحمل الخطأ، ثم لا تسمح للنهاية أن تعيد كتابة جودة البداية». ثم أعطى المدرس الطلاب قصة مشروع انتهى بخسارة رغم أن صاحبه اتبع خطة مشابهة من حيث جمع المعلومات والاحتياط والقدرة على الرجوع. طلب منهم تقييم القرارين قبل معرفة النهايتين. تقاربت الأحكام أكثر بكثير من تقييمهم الأول بعد رؤية النتائج، ما كشف قوة الانحياز اللاحق. كما ناقشوا أن العملية الجيدة لا تضمن النجاح؛ هي تقلل الأخطاء التي كان يمكن تجنبها وتوضح مقدار المخاطرة التي اختيرت بوعي. هذا الفصل جعل النقد السردي والتحليل المالي يلتقيان في سؤال جودة القرار لا في الاحتفال بالنتيجة أو إدانتها.''',",
"قالت المحللة إن المؤسسة تحتاج إلى ماض يمكن نقده لا أسطورة تمنح الحاضر شرعية تلقائية، وتحتاج إلى مؤشرات تساعدها على العمل لا أرقام تعيد تعريف رسالتها بصمت. عندما يظهر تاريخ الاختيارات، يصبح التغيير قرارًا يمكن تفسيره بدل أن يبدو خيانة للماضي أو استمرارًا حتميًا له.''',":"قالت المحللة إن المؤسسة تحتاج إلى ماض يمكن نقده لا أسطورة تمنح الحاضر شرعية تلقائية، وتحتاج إلى مؤشرات تساعدها على العمل لا أرقام تعيد تعريف رسالتها بصمت. عندما يظهر تاريخ الاختيارات، يصبح التغيير قرارًا يمكن تفسيره بدل أن يبدو خيانة للماضي أو استمرارًا حتميًا له. ثم أضاف الفريق مساحة في العرض تسأل الزائر والموظف أي جزء من الرسالة الحالية يعتقد أنه امتداد قديم وأي جزء يراه استجابة لظروف جديدة. لم تُعامل الإجابات كحقائق تاريخية، لكنها كشفت كيف تعمل الذاكرة داخل المؤسسة اليوم. قورنت هذه الانطباعات بالوثائق والسجلات، فظهر أين تتوافق الهوية المتداولة مع الأرشيف وأين تختصر تاريخًا أكثر تعقيدًا. أصبح هذا الفرق موضوعًا للتعلم بدل محاولة إزالة التوتر بين الماضي والحاضر بالكامل.''',",
"قالت سلمى إن هذا هو الاستعداد للمستوى التالي: ليس حفظ مفردات أصعب، بل القدرة على إدارة حجة طويلة متعددة الطبقات، ومقاومة الإغراء بأن تجعل التعقيد اللغوي بديلاً عن وضوح التفكير.''',":"قالت سلمى إن هذا هو الاستعداد للمستوى التالي: ليس حفظ مفردات أصعب، بل القدرة على إدارة حجة طويلة متعددة الطبقات، ومقاومة الإغراء بأن تجعل التعقيد اللغوي بديلاً عن وضوح التفكير. وفي الاختبار الأخير قدم المدرس نصًا يحتوي على جمل فصيحة طويلة لكنها تخفي انتقالين غير مبررين، ونصًا أبسط يحمل حجة متعددة الأدلة والبدائل. طلب من الطلاب تقييم بنية الاستدلال قبل الأسلوب. نجحوا عندما استطاعوا كشف القفزة في النص الأول وشرح لماذا يبقى الثاني مركبًا رغم وضوح عباراته. ثم أعادوا كتابة الجزء الضعيف بحيث يضيف المقدمة الناقصة أو يضيق النتيجة. بهذه الخطوة أصبح التقدم مرتبطًا بالقدرة على إصلاح الحجة، لا بمجرد اكتشاف عيب فيها.''',",
}
for old,new in patches.items():
    assert text.count(old)==1, f'expected one Unit10 retry insertion point: {old[:50]!r}'
    text=text.replace(old,new)
exec(compile(text,str(SOURCE),'exec'),{'__name__':'__main__','__file__':str(SOURCE)})
